unsafe fn putd(o:*mut u8,p:usize,x:f64){for(k,b)in x.to_le_bytes().iter().enumerate(){*o.add(p+k)=*b}}
#[no_mangle]
pub unsafe extern "C" fn fuzzy_operations(v:*const i64,n:usize,o:*mut u8,cap:usize)->i64{if v.is_null()||n!=8{return -1}let a=std::slice::from_raw_parts(v,n);let op=a[0];if !(0..=3).contains(&op)||a[1..].iter().any(|x|!(0..=1000).contains(x)){return -1}if op==0{if a[4..].iter().any(|x|*x!=0){return -1}}else if op==1||op==2{if a[7]!=0{return -1}}else if a[4]!=0||a[5]!=0||a[6]!=0||!(a[1]<a[2]&&a[2]<a[3]){return -1}let size=if op==3{8}else{24};if o.is_null()||cap<size{return -2}let l=a[1] as f64/1000.;let p=a[2] as f64/1000.;let r=a[3] as f64/1000.;match op{0=>{putd(o,0,1.-r);putd(o,8,1.-l);putd(o,16,1.-p);24},1=>{putd(o,0,l.max(a[4] as f64/1000.));putd(o,8,r.min(a[6] as f64/1000.));putd(o,16,(p+a[5] as f64/1000.)/2.);24},2=>{putd(o,0,l.min(a[4] as f64/1000.));putd(o,8,(p+a[5] as f64/1000.)/2.);putd(o,16,r.max(a[6] as f64/1000.));24},_=>{let x=a[7] as f64/1000.;let y=if x<=l||x>=r{0.}else if x<=p{(x-l)/(p-l)}else{(r-x)/(r-p)};putd(o,0,y);8}}}
